window.DISCRETE_MATHEMATICS_DIAGNOSTIC=[{"id":"diagnostic-01","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Which is a proposition?","options":["7 is prime.","Close the door.","What time is it?","x+2=5"],"answer":0,"explanation":"A proposition has a definite truth value."},{"id":"diagnostic-02","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Negation of “p and q” is…","options":["not p or not q","not p and not q","p or q","p implies q"],"answer":0,"explanation":"De Morgan’s law gives ¬(p∧q)≡¬p∨¬q."},{"id":"diagnostic-03","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"p→q is false only when…","options":["p is true and q is false","p and q are true","p is false","q is true"],"answer":0,"explanation":"An implication fails only with a true premise and false conclusion."},{"id":"diagnostic-04","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The contrapositive of p→q is…","options":["not q→not p","q→p","not p→not q","p and not q"],"answer":0,"explanation":"The contrapositive is logically equivalent."},{"id":"diagnostic-05","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Negation of “for every x, P(x)” is…","options":["there exists x with not P(x)","for every x, not P(x)","there exists x with P(x)","P(x) is always true"],"answer":0,"explanation":"Negating a universal produces an existential counterexample."},{"id":"diagnostic-06","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"If A={1,2} and B={2,3}, A∩B is…","options":["{2}","{1,2,3}","{1,3}","empty"],"answer":0,"explanation":"Intersection contains common elements."},{"id":"diagnostic-07","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A three-element set has how many subsets?","options":["8","6","3","9"],"answer":0,"explanation":"A set of size n has 2^n subsets."},{"id":"diagnostic-08","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A function assigns each domain element…","options":["exactly one output","at least two outputs","no codomain","one input only"],"answer":0,"explanation":"A function is single-valued on its domain."},{"id":"diagnostic-09","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A bijection is…","options":["injective and surjective","only injective","only surjective","constant"],"answer":0,"explanation":"A bijection is one-to-one and onto."},{"id":"diagnostic-10","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"An equivalence relation is…","options":["reflexive, symmetric, transitive","reflexive, antisymmetric, transitive","symmetric only","irreflexive"],"answer":0,"explanation":"These three properties characterize equivalence relations."},{"id":"diagnostic-11","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"To refute a universal statement, one needs…","options":["one valid counterexample","many examples","an analogy","a diagram only"],"answer":0,"explanation":"One counterexample disproves a universal claim."},{"id":"diagnostic-12","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A direct proof of p→q begins by…","options":["assuming p","assuming not q","assuming q","assuming not p"],"answer":0,"explanation":"Use the hypothesis to derive the conclusion."},{"id":"diagnostic-13","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Mathematical induction requires…","options":["a base case and inductive step","only examples","a truth table","a contradiction every time"],"answer":0,"explanation":"Both parts are required."},{"id":"diagnostic-14","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A loop invariant should be…","options":["true before and preserved by each iteration","false at termination","a timing measurement","an unproved guess"],"answer":0,"explanation":"Initialization and preservation support correctness."},{"id":"diagnostic-15","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"47 divided by 6 leaves remainder…","options":["5","7","1","6"],"answer":0,"explanation":"47=6·7+5."},{"id":"diagnostic-16","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"gcd(18,24) is…","options":["6","3","12","72"],"answer":0,"explanation":"Six is the greatest common divisor."},{"id":"diagnostic-17","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"17 mod 5 is…","options":["2","3","5","12"],"answer":0,"explanation":"17=5·3+2."},{"id":"diagnostic-18","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The inverse of 3 mod 7 is…","options":["5","2","3","6"],"answer":0,"explanation":"3·5≡1 mod 7."},{"id":"diagnostic-19","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"5! equals…","options":["120","25","60","720"],"answer":0,"explanation":"5·4·3·2·1=120."},{"id":"diagnostic-20","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"C(6,2) equals…","options":["15","12","30","8"],"answer":0,"explanation":"6·5/(2·1)=15."},{"id":"diagnostic-21","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The pigeonhole principle guarantees…","options":["some box receives at least the ceiling average","all boxes are equal","no collisions","randomness"],"answer":0,"explanation":"Distribution across boxes forces concentration."},{"id":"diagnostic-22","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Inclusion–exclusion corrects for…","options":["overlap","order only","negative numbers","rounding"],"answer":0,"explanation":"Overlapping cases are otherwise double counted."},{"id":"diagnostic-23","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"For a_n=2a_{n−1}, a_0=1, a_3 is…","options":["8","6","4","3"],"answer":0,"explanation":"The sequence is 1,2,4,8."},{"id":"diagnostic-24","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A graph is G=(V,E), where V contains…","options":["vertices","weights only","paths only","truth values"],"answer":0,"explanation":"V is the vertex set."},{"id":"diagnostic-25","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The sum of degrees in an undirected graph equals…","options":["2|E|","|E|","|V|","|V|+|E|"],"answer":0,"explanation":"Every edge contributes two to the degree sum."},{"id":"diagnostic-26","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A connected graph has an Euler circuit when…","options":["every vertex has even degree","every vertex has odd degree","it is complete","it is bipartite"],"answer":0,"explanation":"This is the Euler-circuit characterization."},{"id":"diagnostic-27","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"BFS uses a…","options":["queue","priority stack only","set formula","truth table"],"answer":0,"explanation":"Breadth-first search processes a queue."},{"id":"diagnostic-28","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A tree with n vertices has…","options":["n−1 edges","n edges","2n edges","one edge"],"answer":0,"explanation":"Every finite tree has n−1 edges."},{"id":"diagnostic-29","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A spanning tree must…","options":["include every vertex and contain no cycle","include every edge","be complete","have equal weights"],"answer":0,"explanation":"It is a connected acyclic spanning subgraph."},{"id":"diagnostic-30","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Dijkstra’s standard algorithm assumes…","options":["nonnegative edge weights","all weights equal","a tree only","negative cycles"],"answer":0,"explanation":"Nonnegative weights justify finalization."},{"id":"diagnostic-31","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A topological ordering exists exactly for…","options":["directed acyclic graphs","all undirected graphs","complete graphs","graphs with Euler circuits"],"answer":0,"explanation":"A directed cycle prevents such an order."},{"id":"diagnostic-32","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A graph is bipartite exactly when it has…","options":["no odd cycle","no even cycle","no vertices","all degrees two"],"answer":0,"explanation":"This is the standard characterization."},{"id":"diagnostic-33","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Boolean absorption says x+x·y equals…","options":["x","y","x+y","0"],"answer":0,"explanation":"The extra term adds nothing beyond x."},{"id":"diagnostic-34","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A deterministic finite automaton has…","options":["one next state for each state-symbol pair","infinitely many required states","no accepting states","only one input string"],"answer":0,"explanation":"Its transition function is single-valued."},{"id":"diagnostic-35","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"3n²+4n+7 is…","options":["Theta(n²)","Theta(n)","Theta(2^n)","Theta(log n)"],"answer":0,"explanation":"The quadratic term dominates asymptotically."},{"id":"diagnostic-36","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A correctness proof often uses…","options":["preconditions, invariants, and postconditions","timing alone","examples alone","compiler success only"],"answer":0,"explanation":"These establish logical correctness."},{"id":"diagnostic-37","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A mapping reduction is used to…","options":["relate the difficulty or decidability of problems","draw a graph only","sort numbers","estimate probability"],"answer":0,"explanation":"It transforms instances while preserving yes/no structure."},{"id":"diagnostic-38","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Hamming distance counts…","options":["positions where strings differ","the number of strings","the length only","matching positions"],"answer":0,"explanation":"It counts coordinate disagreements."},{"id":"diagnostic-39","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"SAT asks whether…","options":["a Boolean formula has a satisfying assignment","a graph is connected","a number is prime","a tree is balanced"],"answer":0,"explanation":"SAT is the Boolean satisfiability problem."},{"id":"diagnostic-40","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A reproducible discrete-math solution should preserve…","options":["definitions, proof steps, algorithms, tests, and limitations","only the final answer","only a screenshot","only execution time"],"answer":0,"explanation":"An audit trail supports verification."}];
